require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/session.php';require_once __DIR__.'/../includes/functions.php';if(!is_attendee_logged_in())redirect('../index.php');
$profileResult=pg_query_params($conn,'SELECT must_complete_profile,qr_token FROM attendees WHERE id=$1',[$_SESSION['attendee_id']]);$profile=$profileResult&&pg_num_rows($profileResult)?pg_fetch_assoc($profileResult):null;if(!$profile)redirect('../logout.php');if($profile['must_complete_profile']==='t'||$profile['must_complete_profile']===true)redirect('onboarding.php');if(empty($profile['qr_token'])){$profile['qr_token']=bin2hex(random_bytes(24));pg_query_params($conn,'UPDATE attendees SET qr_token=$1 WHERE id=$2',[$profile['qr_token'],$_SESSION['attendee_id']]);}$qrPayload='AMS:'.$profile['qr_token'];
$message=$_SESSION['attendance_message']??'';$error=$_SESSION['attendance_error']??'';unset($_SESSION['attendance_message'],$_SESSION['attendance_error']);
$result=pg_query_params($conn,"SELECT r.id registration_id,r.ticket_code,r.status registration_status,e.*,ar.check_in_at,ar.check_out_at FROM event_registrations r JOIN events e ON e.id=r.event_id LEFT JOIN attendance_records ar ON ar.registration_id=r.id WHERE r.attendee_id=$1 ORDER BY e.start_at DESC",[$_SESSION['attendee_id']]);$events=$result?(pg_fetch_all($result)?:[]):[];$registered=count(array_filter($events,fn($e)=>$e['registration_status']==='registered'));$attended=count(array_filter($events,fn($e)=>!empty($e['check_in_at'])));$upcoming=count(array_filter($events,fn($e)=>in_array($e['status'],['open','ongoing'],true)&&empty($e['check_in_at'])));
