function toggleTheme(){const d=document.documentElement,n=d.getAttribute('data-theme')==='dark';if(n){d.removeAttribute('data-theme');localStorage.setItem('vms-theme','light')}else{d.setAttribute('data-theme','dark');localStorage.setItem('vms-theme','dark')}updateIcon()}function updateIcon(){const i=document.getElementById('themeIcon');if(i)i.className=document.documentElement.getAttribute('data-theme')==='dark'?'fas fa-sun':'fas fa-moon'}function downloadQr(){const canvas=document.querySelector('#personalQr canvas'),img=document.querySelector('#personalQr img'),a=document.createElement('a');a.download='attendance-qr-<?=h($_SESSION['attendee_code'])?>.png';a.href=canvas?canvas.toDataURL('image/png'):img.src;a.click()}updateIcon();new QRCode(document.getElementById('personalQr'),{text:<?=json_encode($qrPayload,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,width:210,height:210,correctLevel:QRCode.CorrectLevel.H});
</script></body></html>
